s1.willCall(() => 'mocked');
console.log("After spy:", foo1.f());
s1.restore();
console.log("After restore:", foo1.f());
console.log("Own descriptor after restore:", Object.getOwnPropertyDescriptor(foo1, 'f'));
// Expected: undefined (no own property should remain)

// Test 2: inherited getter with setter
