  _v = 'bar';
  get v(): string { return this._v; }
  set v(v: string) { this._v = v; }
}
class Foo2 extends Bar2 {}
const foo2 = new Foo2();
const s2 = spyOn(foo2, { getter: 'v' }, () => 'mocked');
