try {
  foo2.v = 'test';
  console.log("Setter works (no throw)");
} catch (e: any) {
  console.log("Setter THREW:", e.message);
}
console.log("After set:", foo2.v); // Expected: 'mocked'
s2.restore();
console.log("After restore:", foo2.v); // Expected: 'test'

