  createInternalSpy,
  isMockFunction,
  populateSpy,
  spies,
  SpyImpl,
  SpyInternal,
  SpyInternalImpl,
} from './internal.js'
import { assert, define, defineValue, descriptors, isType } from './utils.js'
import { SYMBOL_STATE } from './constants.js'

type Procedure = (...args: any[]) => any

type Methods<T> = {
  [K in keyof T]: T[K] extends Procedure ? K : never
}[keyof T]
type Getters<T> = {
  [K in keyof T]: T[K] extends Procedure ? never : K
}[keyof T]
type Constructors<T> = {
  [K in keyof T]: T[K] extends new (...args: any[]) => any ? K : never
}[keyof T]

let getDescriptor = (obj: any, method: string | symbol | number) =>
  Object.getOwnPropertyDescriptor(obj, method)

let findInPrototypeChain = (
  obj: any,
  method: string | symbol | number
): PropertyDescriptor | undefined => {
  let current = obj
  while (current) {
    let desc = Object.getOwnPropertyDescriptor(current, method)
    if (desc) return desc
    current = Object.getPrototypeOf(current)
  }
  return undefined
}

