console.log("Mocked:", leaf.deep); // mocked
s1.restore();
console.log("Restored:", leaf.deep); // base

// Edge case 2: Own method spy + restore (should still work)
console.log("\n=== Edge 2: Own method spy + restore ===");
class Own { myMethod() { return 'own'; } }
const own = new Own();
const s2 = spyOn(own, 'myMethod');
s2.willCall(() => 'mocked-own');
console.log("Mocked:", own.myMethod()); // mocked-own
s2.restore();
console.log("Restored:", own.myMethod()); // own
console.log("Own descriptor:", Object.getOwnPropertyDescriptor(own, 'myMethod')); // should still be there if was own

