console.log("Mocked getter:", og.x); // 999
og.x = 50;
console.log("After set:", og.x); // 999 (still mocked)
s3.restore();
console.log("Restored getter:", og.x); // 50
og.x = 77;
console.log("After set post-restore:", og.x); // 77

