console.log("=== Edge 1: Deep prototype chain getter ===");
class Base { get deep() { return 'base'; } }
class Mid extends Base {}
class Leaf extends Mid {}
const leaf = new Leaf();
const s1 = spyOn(leaf, { getter: 'deep' }, () => 'mocked');
console.log("Mocked:", leaf.deep); // mocked
s1.restore();
console.log("Restored:", leaf.deep); // base

// Edge case 2: Own method spy + restore (should still work)
console.log("\n=== Edge 2: Own method spy + restore ===");
class Own { myMethod() { return 'own'; } }
const own = new Own();
const s2 = spyOn(own, 'myMethod');
s2.willCall(() => 'mocked-own');
console.log("Mocked:", own.myMethod()); // mocked-own
s2.restore();
console.log("Restored:", own.myMethod()); // own
console.log("Own descriptor:", Object.getOwnPropertyDescriptor(own, 'myMethod')); // should still be there if was own

// Edge case 3: Own getter spy + restore
console.log("\n=== Edge 3: Own getter spy + restore ===");
class OwnGetter {
  _x = 10;
  get x() { return this._x; }
  set x(v: number) { this._x = v; }
}
const og = new OwnGetter();
const s3 = spyOn(og, { getter: 'x' }, () => 999);
console.log("Mocked getter:", og.x); // 999
og.x = 50;
console.log("After set:", og.x); // 999 (still mocked)
s3.restore();
console.log("Restored getter:", og.x); // 50
og.x = 77;
console.log("After set post-restore:", og.x); // 77

